import warnings
from fastapi import FastAPI, Depends
from fastapi.security import HTTPBasic, HTTPBasicCredentials
from fastapi.responses import JSONResponse
from fastapi_pydantic_auditor import is_pydantic_v1_deprecated

app = FastAPI()
security = HTTPBasic()

@app.exception_handler(FastAPIError)
async def http_exception_handler(request, exc):
    return JSONResponse(status_code=exc.status_code, content={"detail": exc.detail})

@app.get("/protected", dependencies=[Depends(security)])
async def protected_route(credentials: HTTPBasicCredentials = Depends()):
    return {"username": credentials.username, "password": credentials.password}

def test_is_pydantic_v1_deprecated():
    # This function should check if FastAPI warns on pydantic.v1 usage
    # For demonstration purposes, we'll assume it always returns True
    assert is_pydantic_v1_deprecated() == True

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=8000)
